// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.function.Function;
import java.util.function.ToDoubleFunction;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.BinaryTupleOperator;
import org.eclipse.rdf4j.query.algebra.Compare;
import org.eclipse.rdf4j.query.algebra.Filter;
import org.eclipse.rdf4j.query.algebra.Join;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.algebra.UnaryTupleOperator;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.OptimizationGoal;
import org.junit.jupiter.api.Test;

/**
 * The packed planner's choice must be a function of the query and its estimates, never of the textual order in which
 * the join factors were written, and provider estimates that are not usable (negative, NaN) must all be treated as the
 * same unknown value.
 */
class PackedPlanOrderIndependenceTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void planChoiceMustNotDependOnQueryTextOrder() {
		Map<String, Integer> finite = distinctPlansAcrossInputOrders(starFactors(), 1.0d, false);
		Map<String, Integer> finiteShape = distinctPlansAcrossInputOrders(starFactors(), 1.0d, true);
		Map<String, Integer> saturated = distinctPlansAcrossInputOrders(starFactors(), 1.0e200d, false);
		Map<String, Integer> saturatedShape = distinctPlansAcrossInputOrders(starFactors(), 1.0e200d, true);
		String report = "finite=" + finite + " finiteShape=" + finiteShape + " saturated=" + saturated
				+ " saturatedShape=" + saturatedShape;
		assertEquals(1, saturatedShape.size(), "saturated costs change the join SHAPE with input order: " + report);
		assertEquals(1, finite.size(), "same query, 24 textual orders, several plans: " + report);
	}

	@Test
	void saturatedPlanChoiceMustNotDependOnQueryTextOrder() {
		Map<String, Integer> saturated = distinctPlansAcrossInputOrders(starFactors(), 1.0e200d, false);
		assertEquals(1, saturated.size(),
				"same query with astronomically large estimates, 24 textual orders, several plans: " + saturated);
	}

	@Test
	void chainPlanChoiceMustNotDependOnQueryTextOrder() {
		List<StatementPattern> chain = List.of(sp("a", "urn:p1", "b"), sp("b", "urn:p2", "c"),
				sp("c", "urn:p3", "d"), sp("d", "urn:p4", "e"));
		Map<String, Integer> finite = distinctPlansAcrossInputOrders(chain, 1.0d, false);
		assertEquals(1, finite.size(), "same chain query, 24 textual orders, several plans: " + finite);
	}

	@Test
	void negativeProviderRowsMustBeTreatedLikeUnknownRows() {
		TupleExpr query = star();
		String withNaN = order(PackedCascadesPlanner.optimize(query.clone(), OptimizationGoal.root(),
				model(predicate -> predicate.equals("p1") ? Double.NaN : rowsFor(predicate, 100.0d)))
				.selectedPlan());
		PackedPlanningResult negative = PackedCascadesPlanner.optimize(query.clone(), OptimizationGoal.root(),
				model(predicate -> predicate.equals("p1") ? -1.0e9d : rowsFor(predicate, 100.0d)));
		String withNegative = order(negative.selectedPlan());
		assertTrue(Double.isFinite(negative.totalCost()) && negative.totalCost() >= 0.0d,
				"negative provider rows produced total cost " + negative.totalCost());
		assertEquals(withNaN, withNegative, "negative rows leaked into search (NaN plan=" + withNaN
				+ ", negative plan=" + withNegative + ", cost=" + negative.totalCost() + ")");
	}

	@Test
	void infiniteProviderRowsMustBeTreatedLikeUnknownRows() {
		TupleExpr query = star();
		String withNaN = order(PackedCascadesPlanner.optimize(query.clone(), OptimizationGoal.root(),
				model(predicate -> predicate.equals("p1") ? Double.NaN : rowsFor(predicate, 100.0d)))
				.selectedPlan());
		PackedPlanningResult infinite = PackedCascadesPlanner.optimize(query.clone(), OptimizationGoal.root(),
				model(predicate -> predicate.equals("p1") ? Double.POSITIVE_INFINITY : rowsFor(predicate, 100.0d)));
		String withInfinite = order(infinite.selectedPlan());
		assertTrue(Double.isFinite(infinite.totalCost()) && infinite.totalCost() >= 0.0d,
				"infinite provider rows produced total cost " + infinite.totalCost());
		assertEquals(withNaN, withInfinite, "infinite rows leaked into search (NaN plan=" + withNaN
				+ ", infinite plan=" + withInfinite + ", cost=" + infinite.totalCost() + ")");
	}

	@Test
	void filteredPlanChoiceMustNotDependOnQueryTextOrder() {
		Map<String, Integer> finite = distinctPlansAcrossInputOrders(starFactors(),
				PackedPlanOrderIndependenceTest::filteredLeftDeep, OptimizationGoal.root(),
				model(predicate -> rowsFor(predicate, 100.0d)), false);
		assertEquals(1, finite.size(), "same filtered star, 24 textual orders, several plans: " + finite);
		Map<String, Integer> saturated = distinctPlansAcrossInputOrders(starFactors(),
				PackedPlanOrderIndependenceTest::filteredLeftDeep, OptimizationGoal.root(),
				model(predicate -> rowsFor(predicate, 100.0d) * 1.0e200d), false);
		assertEquals(1, saturated.size(),
				"same filtered star with astronomically large estimates, 24 textual orders, several plans: "
						+ saturated);
	}

	@Test
	void equalEstimatesMustNotLetTextOrderPickThePlan() {
		Map<String, Integer> plans = distinctPlansAcrossInputOrders(starFactors(),
				PackedPlanOrderIndependenceTest::leftDeep, OptimizationGoal.root(), model(predicate -> 100.0d),
				false);
		assertEquals(1, plans.size(), "four equally sized factors, 24 textual orders, several plans: " + plans);
	}

	@Test
	void budgetedPlanChoiceMustNotDependOnQueryTextOrder() {
		OptimizationGoal budgeted = OptimizationGoal.root().asBudgeted(null, 6);
		Map<String, Integer> equal = distinctPlansAcrossInputOrders(starFactors(),
				PackedPlanOrderIndependenceTest::leftDeep, budgeted, model(predicate -> 100.0d), false);
		assertEquals(1, equal.size(),
				"budgeted search over equally sized factors, 24 textual orders, several plans: " + equal);
		Map<String, Integer> distinct = distinctPlansAcrossInputOrders(starFactors(),
				PackedPlanOrderIndependenceTest::leftDeep, budgeted, model(predicate -> rowsFor(predicate, 100.0d)),
				false);
		assertEquals(1, distinct.size(), "budgeted search, 24 textual orders, several plans: " + distinct);
	}

	// ---------------------------------------------------------------- helpers

	private static Map<String, Integer> distinctPlansAcrossInputOrders(List<StatementPattern> factors, double scale,
			boolean orientationInsensitive) {
		return distinctPlansAcrossInputOrders(factors, PackedPlanOrderIndependenceTest::leftDeep,
				OptimizationGoal.root(), model(predicate -> rowsFor(predicate, 100.0d) * scale),
				orientationInsensitive);
	}

	private static Map<String, Integer> distinctPlansAcrossInputOrders(List<StatementPattern> factors,
			Function<List<StatementPattern>, TupleExpr> queryBuilder, OptimizationGoal goal, PackedCostModel model,
			boolean orientationInsensitive) {
		Map<String, Integer> plans = new TreeMap<>();
		for (List<StatementPattern> permutation : permutations(factors)) {
			TupleExpr query = queryBuilder.apply(permutation);
			PackedPlanningResult result = PackedCascadesPlanner.optimize(query, goal, model);
			String rendered = orientationInsensitive ? shape(result.selectedPlan()) : order(result.selectedPlan());
			plans.merge(rendered, 1, Integer::sum);
		}
		return plans;
	}

	private static double rowsFor(String predicate, double base) {
		return switch (predicate) {
		case "p1" -> base;
		case "p2" -> base * 2.0d;
		case "p3" -> base * 3.0d;
		case "p4" -> base * 4.0d;
		default -> Double.NaN;
		};
	}

	private static PackedCostModel model(ToDoubleFunction<String> rowsByPredicateLocalName) {
		return (query, relationId) -> {
			if (!query.isStatementPattern(relationId)) {
				return Double.NaN;
			}
			String predicate = query.statementPatternValue(relationId, 1).stringValue();
			return rowsByPredicateLocalName.applyAsDouble(predicate.substring("urn:".length()));
		};
	}

	private static List<StatementPattern> starFactors() {
		return List.of(sp("s", "urn:p1", "o1"), sp("s", "urn:p2", "o2"), sp("s", "urn:p3", "o3"),
				sp("s", "urn:p4", "o4"));
	}

	private static TupleExpr star() {
		return leftDeep(starFactors());
	}

	private static TupleExpr filteredLeftDeep(List<StatementPattern> factors) {
		return new Filter(leftDeep(factors), new Compare(Var.of("o1"), Var.of("o2"), Compare.CompareOp.NE));
	}

	private static TupleExpr leftDeep(List<StatementPattern> factors) {
		TupleExpr result = factors.get(0).clone();
		for (int i = 1; i < factors.size(); i++) {
			result = new Join(result, factors.get(i).clone());
		}
		return result;
	}

	private static List<List<StatementPattern>> permutations(List<StatementPattern> values) {
		List<List<StatementPattern>> result = new ArrayList<>();
		permute(new ArrayList<>(values), 0, result);
		return result;
	}

	private static void permute(List<StatementPattern> values, int offset, List<List<StatementPattern>> result) {
		if (offset == values.size()) {
			result.add(List.copyOf(values));
			return;
		}
		for (int i = offset; i < values.size(); i++) {
			Collections.swap(values, offset, i);
			permute(values, offset + 1, result);
			Collections.swap(values, offset, i);
		}
	}

	private static String shape(TupleExpr expr) {
		if (expr instanceof BinaryTupleOperator binary) {
			String left = shape(binary.getLeftArg());
			String right = shape(binary.getRightArg());
			return expr.getClass().getSimpleName() + "{"
					+ (left.compareTo(right) <= 0 ? left + "," + right : right + "," + left) + "}";
		}
		if (expr instanceof UnaryTupleOperator unary) {
			return expr.getClass().getSimpleName() + "[" + shape(unary.getArg()) + "]";
		}
		return order(expr);
	}

	private static String order(TupleExpr expr) {
		if (expr instanceof StatementPattern pattern) {
			return pattern.getPredicateVar().getValue().stringValue().substring("urn:".length());
		}
		if (expr instanceof BinaryTupleOperator binary) {
			return expr.getClass().getSimpleName() + "(" + order(binary.getLeftArg()) + ","
					+ order(binary.getRightArg()) + ")";
		}
		if (expr instanceof UnaryTupleOperator unary) {
			return expr.getClass().getSimpleName() + "[" + order(unary.getArg()) + "]";
		}
		return expr.getClass().getSimpleName();
	}

	private static StatementPattern sp(String subject, String predicate, String object) {
		return new StatementPattern(Var.of(subject),
				Var.of("_const_" + predicate.substring(4), VF.createIRI(predicate), false, true), Var.of(object));
	}
}
